#include <iostream>
#include <random>
#include <vector>
#include <fstream>
#include <algorithm>
int main(){
 int n,lo,hi;long long seed;
 if(!(std::cin>>n>>seed>>lo>>hi)||n<0||n>128||seed<0||seed>4294967295LL||lo< -1000||hi>1000||lo>hi){std::cout<<"invalid\n";return 0;}
 std::cin>>std::ws;if(!std::cin.eof()){std::cout<<"invalid\n";return 0;}
 std::mt19937 a(static_cast<std::mt19937::result_type>(seed)),b(static_cast<std::mt19937::result_type>(seed));
 std::uniform_int_distribution<int>da(lo,hi),db(lo,hi);
 std::vector<int>x,y;for(int i=0;i<n;++i){x.push_back(da(a));y.push_back(db(b));}
 bool bounded=std::all_of(x.begin(),x.end(),[lo,hi](int value){return value>=lo&&value<=hi;});
 std::ofstream first("samples.txt"),second("repeat.txt");if(!first||!second){std::cout<<"io-error\n";return 0;}
 for(int value:x)first<<value<<'\n';for(int value:y)second<<value<<'\n';first.close();second.close();
 if(!first||!second){std::cout<<"io-error\n";return 0;}
 std::cout<<"count "<<x.size()<<"\nrepeatable "<<(x==y?"yes":"no")<<"\nbounded "<<(bounded?"yes":"no")<<'\n';
}
